#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> a(n);
    int maximum = 0;

    for (int& value : a) {
        cin >> value;
        maximum = max(maximum, value);
    }

    vector<int> b(maximum, 0);

    for (int i = 0, j = 0; j < maximum; ++i) {
        if (i == n) {
            ++j;
            i = 0;
        }

        if (j == maximum)
            break;

        if (a[i] > 0) {
            --a[i];
            ++b[j];
        }
    }

    for (int i = maximum - 1; i >= 0; --i)
        cout << b[i] << ' ';

    cout << '\n';
    return 0;
}

